const lessons = [
  {id:'ch1',no:'01',title:'为什么要抽样？',stage:'建立直觉',text:'从调查中的判断偏差出发，认识抽样要解决的问题与基本语言。',objective:'目标：区分总体、样本与调查结论。',file:'chapter-1.pdf',label:'第 1 章 · Introduction'},
  {id:'ch2',no:'02',title:'简单随机抽样',stage:'核心基础',text:'学习不放回简单随机抽样，理解样本均值、抽样分布与方差。',objective:'目标：说清抽样机制，并解释估计量的变异。',file:'chapter-2.pdf',label:'第 2 章 · Simple Random Sampling',extra:{file:'chapter-2-proof-method.pptx',label:'第 2 章补充 · 另一种证明方法',kind:'PPTX'}},
  {id:'ch3',no:'03',title:'比例与百分比估计',stage:'估计方法',text:'把属性数据转化为比例或百分比问题，掌握相应的估计思路。',objective:'目标：辨认定性变量，并解释比例估计。',file:'chapter-3.pdf',label:'第 3 章 · Sampling Proportions and Percentages'},
  {id:'ch4',no:'04',title:'估计需要多大样本？',stage:'考点应用',text:'围绕精度要求和抽样风险，判断样本量估计需要哪些信息。',objective:'目标：说明样本量由精度与可靠性要求共同决定。',file:'chapter-4.pdf',label:'第 4 章 · The Estimation of Sample Size'},
  {id:'ch5',no:'05',title:'分层随机抽样',stage:'抽样设计',text:'理解总体划分为互不重叠的层，并在各层独立抽样的设计。',objective:'目标：描述分层设计，并理解层权重的作用。',file:'chapter-5.pdf',label:'第 5 章 · Stratified Random Sampling'},
  {id:'ch5a',no:'05A',title:'分层抽样的进一步问题',stage:'进阶理解',text:'关注层权重估计有误时对估计偏差与均方误差的影响。',objective:'目标：解释权重误差为何会带来偏差。',file:'chapter-5a.pdf',label:'第 5A 章 · Further Aspects of Stratified Sampling'},
  {id:'ch6',no:'06',title:'比率估计量',stage:'综合方法',text:'利用辅助变量与目标变量的关系，理解比率参数及其样本估计。',objective:'目标：指出比率估计使用的两类观测及其关系。',file:'chapter-6.pdf',label:'第 6 章 · Ratio Estimators'}
];
const lectures = {
  ch1:{lead:'我们先不背公式。先弄清楚：抽样究竟想替我们回答什么问题？',sections:[
    {title:'1. 抽样不是“随便问几个人”',text:'调查往往想描述一个很大的总体，例如某地区所有家庭的平均支出。逐个测量可能太贵、太慢，甚至会破坏被测对象。抽样就是按一个设计选出一部分单位，用样本信息推断总体。关键不只在“抽多少”，也在“怎么选”。'},
    {title:'2. 先把调查对象说清楚',text:'目标总体是你真正想了解的人或物；抽样框是实际用来抽取单位的名单或登记系统；被抽中的单位叫抽样单位；提供答案的人或记录叫报告单位。抽样框没覆盖夜班学生，即使抽得再随机，也不能自动代表这部分人。'},
    {title:'3. 概率抽样与非概率抽样',text:'概率抽样为总体单位安排已知且大于零的入样机会，因此可以描述“哪些样本可能出现”，并据此计算抽样误差。简单随机抽样是其中一种。便利抽样、判断抽样和配额抽样容易实施，但选择机会通常未知，不能直接用同一套设计公式说明精度。'},
    {title:'4. 两种误差别混为一谈',text:'抽样误差来自只观察总体的一部分；即便抽样无偏，不同随机样本也会略有不同。标准误描述这种重复抽样下的波动。非抽样误差来自漏掉人群、拒访、测量、录入或处理问题。扩大样本通常能减小抽样波动，却不会自动修复错误的名单或含糊的问题。',formula:'估计量的均方误差 MSE = 方差 + 偏差²\n标准误 SE = √方差',tip:'若平均结果很稳定但总是偏高，标准误小也不代表估计准确。'}
  ],example:'例子：想估计本校本科生的通勤时间。目标总体是全体本科生，学籍名册可以作为抽样框，学生是抽样单位，学生本人报告时间。如果名册漏掉交换生，问题属于覆盖/抽样框误差；如果随机样本里有人通勤更久或更短，这种波动属于抽样误差。',question:'随机抽到的学生都回答了，但其中一半把“单程时间”误填成“往返时间”。主要是什么问题？',options:['抽样误差','测量误差','有限总体修正'],answer:1,explanation:'这是问题定义或作答造成的测量误差；增加样本量不能自动把“单程”和“往返”统一。',recap:['先定义目标总体、抽样框和抽样单位。','概率抽样让抽样机制和精度可以被分析。','抽样误差与非抽样误差需要分开诊断。']},
  ch2:{lead:'这一章的核心是一个公平的抽取规则，以及它带来的可计算精度。',sections:[
    {title:'1. 简单随机抽样是什么',text:'从 N 个单位里不放回抽出 n 个单位，并让所有大小为 n 的不同样本都有相同机会。抽中一个单位后，它不会再次入样。逐次抽取时，每一步都在尚未抽中的单位里随机选。'},
    {title:'2. 用样本均值估计总体均值',text:'总体均值是所有 N 个数的平均；样本均值是抽中的 n 个数的平均。因为每个单位的入样机会相同，重复执行抽样后，样本均值的平均会回到总体均值，所以它是无偏估计。估计总体总量时，把样本均值乘以总体规模 N。',formula:'总体均值：Ȳ = (1/N) ΣYᵢ\n样本均值：ȳ = (1/n) Σyᵢ\n总体总量估计：Ŷ = N ȳ'},
    {title:'3. 方差公式在说什么',text:'S² 描述总体单位彼此有多分散；n 越大，均值通常越稳定。f=n/N 是抽样比例。有限总体修正 (1−f) 反映“不放回”带来的额外稳定性：抽走一部分后，剩下可变的单位更少。总体很大且抽样比例很小时，这个修正接近 1，可以近似忽略。',formula:'Var(ȳ) = (1 − f) S² / n， f = n/N\nS² = Σ(Yᵢ − Ȳ)² / (N − 1)\n从样本估计：v(ȳ) = (1 − f)s² / n',tip:'标准误是估计方差的平方根，和原变量单位相同。总量估计 Ŷ 的方差为 N² Var(ȳ)。'},
    {title:'4. 一个小算例',text:'假设总体有 1,000 人，随机抽取 100 人，通勤时间总体标准差约 10 分钟。此时 f=0.1，样本均值方差约为 (1−0.1)×100/100=0.9，标准误约 0.95 分钟。这里的 0.95 是抽样方法的典型波动，不是对某个人测量误差的描述。'},
    {title:'5. 替换与不替换',text:'有放回抽样允许同一个单位多次出现；不放回抽样不允许。其他条件相近时，不放回抽样通常更有效率，有限总体修正正是公式里体现这点的因子。'}
  ],example:'做题顺序：先认出估计目标是均值还是总量；写出 N、n、f；确认抽样是否不放回；最后代入方差或标准误公式。估计总量时不要忘记乘 N，也不要把方差和标准误混在一起。',question:'如果抽样比例 f 很小，忽略有限总体修正 (1−f) 会怎样？',options:['方差估计略偏大，偏保守','方差变成 0','样本均值变成有偏'],answer:0,explanation:'不乘一个接近 1 但小于 1 的修正因子，会略高估不放回抽样的方差。',recap:['SRS 让所有大小相同的样本等可能。','ȳ 是 Ȳ 的无偏估计，Ŷ=N ȳ。','Var(ȳ)=(1−f)S²/n；SE=√Var(ȳ)。']},
  ch3:{lead:'比例题看起来像新章节，其实只是把“属于某类”编码成 1 或 0。',sections:[
    {title:'1. 把类别变成数字',text:'对每个单位定义指示变量：属于目标类别 C 时 yᵢ=1，不属于时 yᵢ=0。总体中 1 的个数是 A，所以总体比例 P=A/N；样本里 1 的个数是 a，所以样本比例 p=a/n。这样比例就变成 0/1 数据的均值。',formula:'P = A/N = Ȳ，  Q = 1 − P\np = a/n，  q = 1 − p\n目标类别总数估计：Â = Np'},
    {title:'2. 为什么 p 可以估计 P',text:'在简单随机抽样下，每个单位都有相同机会进入样本。样本里目标类别的比例平均起来等于总体真实比例，因此 p 是无偏估计。比例越接近 0.5，0/1 数据通常越分散；当 P 已知得不多时，P=0.5 可作为保守规划值。'},
    {title:'3. 比例的标准误',text:'比例估计的抽样波动由 P、Q、样本量和抽样比例共同决定。实际中 P 未知，用样本 p、q 代替来估计标准误。若要估计目标类别的总人数，把比例估计乘 N，标准误也乘 N。',formula:'Var(p) = (1 − n/N) · [N/(N−1)] · PQ/n\n估计方差：v(p) = (1 − n/N) · pq/(n−1)\nSE(Â) = N · SE(p)',tip:'样本里某类人数 a=0 或 a=n 时，样本 pq 会变成 0；这不表示总体比例完全没有不确定性，要谨慎使用正态近似。'},
    {title:'4. 讲义里的地址例题',text:'从 3,042 个姓名地址中简单随机抽取 200 个，发现 38 个地址错误。先算 p=38/200=0.19，即样本中约 19% 地址错误；再估总体错误地址数：Â=3,042×0.19≈578。按有限总体修正计算，讲义给出的估计标准误约为 81.8 个地址。',example:'估计值 578 是中心；标准误 81.8 描述重复抽样的典型波动。若进一步做 95% 区间，粗略用 578 ± 1.96×81.8，约为 418 到 738。正式作答要按题目要求处理连续性修正与区间方法。'},
    {title:'5. 置信区间怎样解释',text:'“95% 置信”描述的是方法：如果按相同设计反复抽样并构造区间，长期约 95% 的区间会覆盖固定的 P。它不是说抽样后固定的 P 有 95% 概率在这一个已算出的区间里。讲义还讨论了有限总体下 a 的超几何分布，以及多类别和子总体比例。'}
  ],example:'看题识别三个量：样本总数 n、目标类别人数 a、总体规模 N。先算 p=a/n，再算 Â=Np；标准误如果问的是比例就不乘 N，如果问总体人数就乘 N。',question:'上例中，38/200 得到的 0.19 直接表示什么？',options:['全体 3,042 个地址中必有 19% 错误','样本中地址错误的比例，并作为总体比例估计','错误地址的估计总数'],answer:1,explanation:'0.19 首先是样本比例 p；乘以 N 后才得到总体错误地址总数估计 Â≈578。',recap:['用 0/1 指示变量把比例写成均值。','p=a/n 估计 P；Â=Np 估计总数。','明确题目问比例还是人数，再报告相应标准误。']},
  ch4:{lead:'样本量不是越大越好。它要回答的是：为了达到目标精度，最少需要抽多少？',sections:[
    {title:'1. 先把“准一点”说成数字',text:'规划前需要指定置信水平、允许误差、总体规模，以及可用的先验波动信息。比例的绝对误差 d 是“最多差几个百分点”；相对误差 r 则是相对目标值的比例。题目没有给精度要求时，不能唯一算出 n。'},
    {title:'2. 比例估计的样本量',text:'在简单随机抽样与正态近似下，目标是让误差界约为 d。令 t 为置信水平对应的正态临界值；95% 常用 t=1.96。先忽略有限总体修正求 n₀，再按 N 修正。若总体比例 P 未知，用 P=0.5，因为 PQ 在 0.5 时最大，给出的样本量比较保守。',formula:'n₀ = t²PQ / d²\n有限总体修正： n = n₀ / [1 + (n₀−1)/N]\n95% 置信： t ≈ 1.96',tip:'d 要用比例单位：允许 ±5 个百分点时，d=0.05，不是 5。'},
    {title:'3. 课件例题：岛上有 3,200 人',text:'想以 95% 置信度把比例估计到 ±0.05；未知 P 时取 P=0.5。先算 n₀=1.96²×0.5×0.5/0.05²≈384；由于 N=3,200 并非无限大，再做有限总体修正：n≈384/[1+383/3200]≈343。实际计划通常向上取整。'},
    {title:'4. 连续变量与多项指标',text:'若要估计平均值，公式里的 PQ 换成总体方差 S²：n₀=t²S²/d²。若要求相对误差 r，规划量受变异系数 CV=S/Ȳ 影响，近似 n₀=t²(CV/r)²。一个调查常有多个指标，应分别算各自所需 n，再结合预算、最重要的指标和可接受精度作决定。'}
  ],example:'样本量变成 4 倍，标准误大致减半，因为标准误通常按 1/√n 变化。想把误差界从 5% 缩到 2.5%，忽略有限总体时样本量大约要变成 4 倍。',question:'比例 P 未知，使用 P=0.5 规划样本量的主要理由是什么？',options:['它让 PQ 最大，得到较保守的 n','它保证最终样本比例一定等于 0.5','它可以省去置信水平'],answer:0,explanation:'PQ=P(1−P) 在 P=0.5 时达到最大；方差取最大值来规划，避免低估样本需求。',recap:['先明确置信水平、误差界和总体规模。','比例 n₀=t²PQ/d²，有限总体再修正。','未知比例用 P=0.5；多个指标要综合精度和预算。']},
  ch5:{lead:'分层的目标不是把总体切得越碎越好，而是让每一层内部更相似、又保留关键群体信息。',sections:[
    {title:'1. 设计：先分层，再在每层随机抽',text:'把总体划分成 L 个互不重叠且合起来覆盖总体的层。第 h 层有 Nₕ 个单位，从该层不放回随机抽 nₕ 个；不同层独立抽样。各层总规模 Nₕ 通常需要已知。'},
    {title:'2. 总体平均要按层大小加权',text:'层内样本均值 ȳₕ 只代表第 h 层。总体均值不是各层均值的简单平均，除非各层规模相同。用层权重 Wₕ=Nₕ/N 加权；总体总量估计则把每层样本均值乘本层规模，再加总。',formula:'Wₕ = Nₕ/N，且 ΣWₕ=1\n总体均值估计： ȳₛₜ = Σ Wₕ ȳₕ\n总体总量估计： Ŷₛₜ = Σ Nₕ ȳₕ\nVar(ȳₛₜ) = Σ Wₕ²(1−fₕ)Sₕ²/nₕ'},
    {title:'3. 为什么分层可能更精确',text:'如果同一层里的单位彼此相似，层内方差 Sₕ² 较小；而不同层均值可以差得很大。分别估每层再加权，相当于避免某次样本碰巧多抽到某类群体而使总体估计偏移。分层还可保证重要子群体都有样本。'},
    {title:'4. 两种常见分配',text:'比例分配 nₕ=nWₕ：大层抽得多，样本权重简单，适合层内方差和调查成本相近。Neyman 分配 nₕ∝NₕSₕ：优先把样本放到规模大且层内变化大的层；若层间成本不同，成本更高的层可少分配。',formula:'比例分配： nₕ = n · Nₕ/N\nNeyman 分配（等成本）： nₕ = n · NₕSₕ / Σ(NₖSₖ)',tip:'最优分配依赖先验 Sₕ 和成本。信息不可靠时，比例分配的简单、稳健也有价值。'},
    {title:'5. 讲义里的城乡家庭例子',text:'城市层 N₁=250，农村层 N₂=500；各层各抽 10 户。层权重分别是 1/3 与 2/3，样本均值分别是 3.2 与 4 人。总体平均估计为 (1/3)×3.2+(2/3)×4≈3.73 人。因为两层样本量相等但层规模不同，不能把 3.2 和 4 直接平均成 3.6。'}
  ],example:'什么时候考虑分层？你需要对某些子群分别报告；不同子群的抽样流程不同；或总体内部差异很大，但可以找到一个分组变量让层内更整齐。',question:'上面的城乡例子，为什么总体估计不能把 3.2 和 4 直接做算术平均？',options:['农村总体规模是城市的两倍，层权重不同','样本量必须先增加到 20','因为 3.2 不是整数'],answer:0,explanation:'总体均值按总体中的层规模加权。农村占 2/3，城市占 1/3，因此加权结果约 3.73。',recap:['先确保分层互不重叠且覆盖总体。','总体估计使用 Wₕ=Nₕ/N 加权。','比例分配简单；Neyman 分配兼顾层规模和层内波动。']},
  ch5a:{lead:'这一节提醒我们：公式算得再精确，也依赖正确的层权重和合理的样本分配。',sections:[
    {title:'1. 权重错了，偏差会留下来',text:'分层均值要乘真实总体权重 Wₕ=Nₕ/N。如果用估计权重 wₕ 替代，而且权重长期偏离真实值，估计量的期望会偏离总体均值。即使每层样本量不断增加、层内均值估得越来越准，错误权重造成的偏差也不会因此消失。',formula:'正确： ȳₛₜ = ΣWₕȳₕ\n使用估计权重： ȳw = Σwₕȳₕ\n权重偏差的贡献约为： Σ(wₕ−Wₕ)Ȳₕ',tip:'实际应用先核对各层总体数量和权重来源，再讨论要不要加样本。'},
    {title:'2. 一个能看见偏差的例子',text:'城乡家庭的真实层权重是城市 1/3、农村 2/3，层均值分别 3.2 和 4。正确加权得到 3.73。若误用 1/2、1/2，得到 3.6，偏低约 0.13 人。把每层样本扩大只会让 3.2 与 4 更精确，不会让错误的 1/2 权重变正确。'},
    {title:'3. 偏离 Neyman 分配的代价',text:'Neyman 分配在给定总样本量、成本相同等前提下最小化估计方差。实际分配不一定正好最优；偏离会增加方差。可用真实与实际分配带来的方差作比较，而不是只凭“各层平均分”判断。若需要保留层间最低样本量，或有多个调查指标，实际方案往往是折中。'},
    {title:'4. 多个指标与分层边界',text:'一个分层方案不可能总是同时对所有指标最优。先确定最重要的调查指标和允许误差，再考虑一个折中分配。分层边界理想上使目标变量在层内较同质、不同层之间较不同；若用辅助变量分层，该变量最好与目标变量相关。分层数量太多会增加管理和估计负担，收益通常逐渐变小。'}
  ],example:'检查一个分层估计时，依次问：层权重是否来自真实总体结构？权重和是否为 1？样本分配是否适合目标变量？有多个指标时，方案如何折中？',question:'若固定使用错误的层权重，只把各层样本量不断加大，最可能出现什么？',options:['层权重偏差会自动消失','抽样方差下降，但权重造成的偏差仍在','总体权重变成相等'],answer:1,explanation:'增大样本能降低层内抽样波动，却不能修正层的加权比例。',recap:['样本量大不能替代正确总体权重。','Neyman 分配是有前提的最优方案，实际常需折中。','分层变量和边界要服务于目标指标。']},
  ch6:{lead:'如果一个已知的辅助变量和目标变量一起变化，它可以帮助我们把总量估得更准。',sections:[
    {title:'1. 先分清 x 和 y',text:'每个抽样单位同时观测一对数值 (xᵢ,yᵢ)。y 是想估计的目标变量；x 是辅助变量，例如上一年完整普查的数值。若总体 x 总量 X 已知，就可以用样本中 y 与 x 的比率，校正简单扩张估计。'},
    {title:'2. 比率估计怎样算',text:'先用样本总和求 r=Σyᵢ/Σxᵢ，再乘已知的总体 X，得到 Y 的估计。估均值时可写成总体 x 均值乘 r。',formula:'样本比率： r = Σyᵢ / Σxᵢ\n总体总量估计： Ŷᴿ = X · r\n总体均值估计： Ȳᴿ = X̄ · r',tip:'不要把“两个样本均值相除”和“两个总量相除”弄混；样本量相同，两者数值相等，但先写清目标参数更不易错。'},
    {title:'3. 比率法什么时候有帮助',text:'当 y 与 x 正相关、关系近似通过原点，且总体 X 已知时，样本比率能抵消一部分因单位规模不同带来的变化。例如用已知的上一年利润总额辅助估计今年利润。若 x 与 y 关系弱、相关方向不合适，或截距关系明显，比例调整可能不如简单扩张。'},
    {title:'4. 公司利润例题',text:'讲义给出 56 家公司的去年利润总额 X=86,436（千美元）；样本抽了 12 家，样本去年利润总和 Σx=16,352，今年利润总和 Σy=18,459。样本比率 r≈1.129。比率估计为 86,436×1.129≈97,574（千美元）。若只用今年样本均值扩张，估计约 86,142。两种结果不同；是否更精确要看 x、y 的关系和比率估计方差，不能只挑更大的数。'},
    {title:'5. 偏差与不确定性',text:'比率是两个随机总和的比值，所以小样本时通常不是严格无偏，分布也可能偏斜。讲义使用大样本近似方差；它关注残差 yᵢ−R xᵢ：比率线越能贴近数据，残差越小，估计通常越稳定。分层抽样里可以分别算层比率再合并，也可以算一个总体综合比率，哪种更合适取决于各层的比率是否相似。',formula:'近似方差的直觉：Var(r) ≈ (1−f) · S²(y−R x) / (n X̄²)\nR 是总体比率；实际计算以讲义给出的样本方差估计式为准。'}
  ],example:'答题步骤：写明已知的总体 X；计算样本 Σy 与 Σx；求 r；代入 Ŷᴿ=Xr；若题目问精度，再用比率残差构造方差估计，并说明大样本近似条件。',question:'使用比率估计前，最需要确认哪项条件？',options:['目标变量 y 与辅助变量 x 有合适的相关关系，且总体 X 已知','样本中所有 x 都必须相同','比率估计在任何样本量下严格无偏'],answer:0,explanation:'比率估计依赖已知总体辅助信息，并希望 x 能解释 y 的变化；小样本下通常会有近似偏差。',recap:['成对观测 x 与 y，且总体 X 已知。','先算 r=Σy/Σx，再算 Ŷᴿ=Xr。','关系合适时可能提高精度；小样本时谨慎看近似。']}
};
const deepDives={
  ch1:{intro:'把一份抽样调查想成一条推理链：先说清想知道谁，再说明怎样抽人，最后说明样本结果能支持什么结论。链条前面定义错了，后面的计算再漂亮也救不回来。',steps:[
    {title:'第一步：把“谁”写成可执行的定义',text:'目标总体必须带上对象、范围和时间。例如“2026 年 9 月在校注册的本科生”，比“学生”清楚。接着找抽样框：哪份名单能让你实际抽人？抽样框与目标总体的差异会形成覆盖误差。抽样单位是被随机选中的实体；报告单位是提供答案的实体，两者可以不是同一个。抽中一个家庭是抽样单位、由户主答题时，家庭与户主的角色要分开写。'},
    {title:'第二步：抽样规则决定推断规则',text:'概率抽样不是“看起来随机”，而是每个总体单位有已知且大于零的入样机会，样本从明确的随机机制产生。这样我们能列举或描述所有可能样本，并计算某个估计量在重复抽样下的分布。便利抽样也可能有用来探索问题，但因为谁更容易被选中往往未知，不能把简单随机抽样的标准误公式直接套上。'},
    {title:'第三步：从样本统计量到抽样分布',text:'假想按同一个抽样方案重复调查很多次。每次样本不同，样本均值或比例也会变化。把所有可能样本对应的估计值及其概率放在一起，就是抽样分布。估计量的期望看它长期平均落在哪里；方差看这些估计值散得多开；偏差是期望减去真实参数。',formula:'Bias(θ̂) = E(θ̂) − θ\nMSE(θ̂) = E[(θ̂−θ)²] = Var(θ̂) + Bias(θ̂)²'},
    {title:'第四步：误差大小与置信度',text:'标准误 SE 是抽样分布标准差的估计，描述设计造成的典型波动。置信区间把“估计值 ± 临界值×标准误”变成一段范围。95% 的正确解释是：按同一方法反复抽样，约 95% 的区间覆盖固定的总体参数。覆盖率不包含测量错误或系统漏样带来的额外风险。'},
    {title:'第五步：把错误来源逐项排查',text:'调查误差不只有抽样误差：抽样框漏人、单位拒访、问题问得不清楚、访员记录错误、数据处理出错，都可能带来非抽样误差。增加 n 通常让抽样标准误按约 1/√n 下降；但若每个人都把“单程”误答成“往返”，大样本会更精确地估错。'}
  ],worked:{title:'校园通勤调查：从问题到误差诊断',steps:['目标：估计本校本科生上学单程通勤时间的总体平均值。','抽样框：选定调查日期的本科生学籍名册；先核对休学、交换生等是否纳入目标定义。','抽样单位：学生；报告单位：学生本人。用简单随机抽样从名单中选 n 人。','统计量：样本通勤时间均值 ȳ，用来估计总体均值 Ȳ；标准误量化不同随机样本造成的波动。','诊断：名册漏掉一类学生是覆盖/框误差；抽中后拒答是无回答问题；把单程误填成往返是测量误差；随机抽到不同学生造成的均值变化才是抽样误差。'],result:'只有最后一项能直接通过扩大样本、优化抽样设计来压低。其余问题要分别改名单、追访、改问卷或改数据流程。'},pitfalls:['“随机”不等于对目标总体有代表性：抽样框可能漏掉目标人群。','标准误小只表示随机波动小，不表示偏差小。','置信区间的 95% 是方法的长期覆盖率，不是参数随机变化的概率。']},
  ch2:{intro:'简单随机抽样（SRS）是后面很多公式的基准设计。学这一章要能从“等机会抽样”走到“均值无偏、方差可算、误差可估”。',steps:[
    {title:'第一步：所有样本等可能',text:'有限总体有 N 个单位，选 n 个且不放回。所有大小为 n 的组合一共有 C(N,n) 个，SRS 规定每个组合概率都是 1/C(N,n)。这不等于每个单位只能有 1/C(N,n) 的入样概率；某单位可以出现在许多组合中，它的边际入样概率是 n/N。'},
    {title:'第二步：用指示变量证明样本均值无偏',text:'定义 Iᵢ=1 表示第 i 个总体单位被抽到，否则为 0。SRS 下 E(Iᵢ)=n/N。样本均值可以写成 ȳ=(1/n)ΣIᵢYᵢ。对它取期望：E(ȳ)=(1/n)ΣE(Iᵢ)Yᵢ=(1/n)(n/N)ΣYᵢ=Ȳ。所以它不是“碰巧平均对”，而是按抽样设计长期无偏。',formula:'P(i 入样)=n/N\nȳ=(1/n)Σ IᵢYᵢ\nE(ȳ)=(1/n)Σ(n/N)Yᵢ=Ȳ'},
    {title:'第三步：理解方差里的三个因素',text:'Var(ȳ)=(1−f)S²/n 有三个直觉：n 增大，平均掉更多个体差异，方差下降；S² 增大，单位差异更大，方差上升；f=n/N 增大，不放回抽样把总体“看过”更多，剩余未知部分更小，所以有限总体修正 (1−f) 下降。S² 用 N−1 作分母，是有限总体抽样理论的定义。'},
    {title:'第四步：从方差到标准误和总量',text:'方差单位是原单位的平方，标准误开平方后回到原单位。估计均值时用 ȳ；估计总量时用 Ŷ=N ȳ，因乘以常数 N，方差乘 N²、标准误乘 N。实际总体 S² 不知道时，以样本方差 s² 替代，得到 v(ȳ)=(1−f)s²/n。',formula:'f=n/N\nVar(ȳ)=(1−f)S²/n， SE(ȳ)=√Var(ȳ)\nŶ=N ȳ， Var(Ŷ)=N²Var(ȳ)\nv(ȳ)=(1−f)s²/n，s²=Σ(yᵢ−ȳ)²/(n−1)'},
    {title:'第五步：不放回为什么更精确',text:'在有放回抽样中，同一个单位可能重复出现；不放回时每次都带来新的单位。对于 SRS，不放回设计相较有放回减少约 1−f 的方差。若 f 很小，例如 N=100,000、n=100，1−f=0.999，影响几乎没有；若抽了总体的一半，修正明显，不能省略。'}
  ],worked:{title:'手算一个 5 人总体',steps:['总体数值为 2、4、6、8、10，因此 N=5、总体均值 Ȳ=(2+4+6+8+10)/5=6。','总体方差 S²=[(2−6)²+(4−6)²+0²+(8−6)²+(10−6)²]/(5−1)=40/4=10。','不放回抽 n=2，抽样比例 f=2/5=0.4。于是 Var(ȳ)=(1−0.4)×10/2=3，理论标准误 √3≈1.73。','若实际抽到 4 和 8，ȳ=6；样本方差 s²=[(4−6)²+(8−6)²]/(2−1)=8。代入样本方差估计：v(ȳ)=(1−0.4)×8/2=2.4，估计 SE≈1.55。'],result:'一个是由已知总体算出的理论方差 3；另一个是只看这次样本得到的方差估计 2.4。实际调查通常只能报告后者。'},pitfalls:['S² 的分母是 N−1；样本方差 s² 的分母是 n−1。','把均值的 SE 当成总量的 SE 会少乘 N。','“无偏”不代表每个样本都等于真值，只代表跨样本平均等于真值。']},
  ch3:{intro:'这一章把抽样均值的理论专门用在 0/1 数据上。把每个单位转成“是/否”，比例、百分比和某类人数就能统一处理。',steps:[
    {title:'第一步：定义指示变量',text:'目标类别记为 C。若单位 i 属于 C，令 yᵢ=1；否则令 yᵢ=0。总体中有 A 个 1，P=A/N；样本中有 a 个 1，p=a/n。因为 0/1 的平均值就是 1 的个数除以总数，所以 P 和 p 分别是总体均值和样本均值。'},
    {title:'第二步：从样本比例到总体比例',text:'SRS 下样本均值无偏，因此 E(p)=P。总体类别人数 A 的估计就是 Np。注意“样本类别人数 a”是已观察到的计数；“总体类别人数估计 Â”是推断值，两者通常不同。百分数只是在比例上乘 100%，方差也要乘 100²，标准误乘 100。',formula:'P=A/N， p=a/n， Â=Np\n百分比 = 100p'},
    {title:'第三步：把一般方差式化成比例方差',text:'0/1 总体的有限总体方差为 S²=N·P·Q/(N−1)，其中 Q=1−P。把它代入 SRS 均值方差 Var(p)=(1−n/N)S²/n，就得到 Var(p)=[(N−n)/(N−1)]·PQ/n。实际 P 未知，用样本 p、q 估计：v(p)=(1−n/N)pq/(n−1)。如果估的是人数 Â=Np，标准误再乘 N。',formula:'S²(0/1) = N·P·Q/(N−1)\nVar(p) = [(N−n)/(N−1)]·PQ/n\nv(p) = (1−n/N)·pq/(n−1)\nv(Â) = N²v(p)'},
    {title:'第四步：什么时候用正态近似',text:'样本比例的抽样分布不是任何样本量下都正态；当目标类或非目标类在样本中很少时，分布会偏斜，正态区间可能覆盖不好。讲义讨论连续性修正 1/(2n) 来改善部分情况下的近似。做题时先看样本量和两类频数，再按课程指定方法构造区间。'},
    {title:'第五步：子总体和多类别',text:'总体分成若干域或类别时，可以对每一域估比例或总数。若要估总体某类别人数，知道域总体规模 Nₕ 时，可把域内估计分别算出再加总。多类别分类则每个类别都可用 0/1 指示变量表示，但这些类别比例之间并不独立，因为总和为 1。'}
  ],worked:{title:'3,042 个地址中估计错误地址',steps:['样本 n=200，其中错误地址 a=38；先计算 p=38/200=0.19，q=0.81。','总量点估计：Â=Np=3,042×0.19=577.98，按地址数约 578 个。','估计比例方差：v(p)=(1−200/3042)×0.19×0.81/(200−1)≈0.000723；SE(p)≈0.0269。','总量标准误：SE(Â)=3,042×0.0269≈81.8 个。95% 粗略区间：0.19±1.96×0.0269≈(0.137,0.243)，换算总数约 (418,738)。'],result:'报告时把“19%”说成样本比例估计，把“约 578 个”说成总体数量估计；二者精度单位不同。区间要注明使用的是近似方法。'},pitfalls:['p=0.19 不是“确定 19% 总体地址错误”，而是总体比例的样本估计。','估总体人数时点估计与标准误都要乘 N；方差要乘 N²。','样本中没观察到某类，不代表总体一定没有该类。']},
  ch4:{intro:'样本量规划是把目标误差反过来解成 n。它不是一个脱离假设的固定数字：精度越高、置信度越高、总体越不稳定，通常都需要更多样本。',steps:[
    {title:'第一步：区分误差界、标准误和置信水平',text:'标准误是抽样分布的典型尺度；误差界 d 是你愿意接受的区间半宽；t 是置信水平对应的临界值。近似正态下，误差界约为 t×SE。95% 双侧区间常取 t=1.96，90% 约取 1.645，99% 约取 2.576。把置信水平提高会提高 t，因而 n 增大。'},
    {title:'第二步：由目标精度解比例样本量',text:'忽略有限总体修正时 Var(p)≈PQ/n，因此 SE≈√(PQ/n)。要求 t√(PQ/n)≤d；两边平方并整理得到 n≥t²PQ/d²。这里 d=0.05 表示允许绝对误差 5 个百分点。若题目要求相对误差，要先把相对误差换成相对于 P 的尺度，不能直接代 d。',formula:'误差界：d ≈ t·SE(p)\nSE(p) ≈ √(PQ/n)\n因此 n₀ = t²PQ/d²'},
    {title:'第三步：有限总体修正从哪来',text:'当 n 相对 N 不小，完整 SRS 方差里有 (1−n/N)。要求 t²PQ(1−n/N)/n≤d²，整理可得有限总体样本量公式 n=n₀/[1+(n₀−1)/N]。n₀ 是先把总体当作很大时需要的样本；修正后 n 不会大于 n₀。N 极大时分母接近 1，修正影响很小。',formula:'n = n₀ / [1 + (n₀−1)/N]\nn₀=t²PQ/d²'},
    {title:'第四步：P 未知时为何用 0.5',text:'PQ=P(1−P) 是关于 P 的抛物线，P=0.5 时最大值 0.25。样本量正比于 PQ；用 0.5 规划能避免因为低估比例方差而样本不足。若已有可信的先验调查或历史数据，可以用对应比例估计，但要说明来源。'},
    {title:'第五步：连续变量与相对误差',text:'估总体均值时 Var(ȳ)≈S²/n，所以绝对误差 d 下 n₀=t²S²/d²。若关心相对误差 r=d/Ȳ，定义变异系数 CV=S/Ȳ，则 n₀≈t²(CV/r)²。S²、P、成本和响应率都是规划输入，未知时可以先做先导调查、借用相似总体数据或做敏感性分析。'}
  ],worked:{title:'岛上 3,200 人，估计血型比例',steps:['题意：95% 置信、误差不超过 ±0.05；N=3,200；P 未知。确定 t=1.96，P=Q=0.5。','先求大总体样本量：n₀=1.96²×0.5×0.5/0.05²=384.16。讲义把中间值写作约 384。','按讲义近似数值做有限总体修正：n≈384/[1+(384−1)/3,200]≈342.95，向上取整为 343。若保留 n₀=384.16 到最后，结果约 343.08；严格保证误差界时应向上取 344。','若岛上人口变成 320,000，修正几乎消失，n 仍接近 384；总体扩大 100 倍不代表样本也要扩大 100 倍。'],result:'复现课件近似答案可写约 343；若把“误差不超过 0.05”作为严格规划条件，全程保留精度并最终向上取整，选 344。作答时说明取整依据。'},pitfalls:['d=5 个百分点应代 0.05；把 5 代入会得到荒谬的小样本量。','先用 t 和 PQ 算 n₀，再做有限总体修正；不要把 N 忘掉。','精度减半时样本量约增至 4 倍，因为 n 与 1/d² 成正比。','多指标调查不是只看平均样本量：关键指标可能决定最低 n。']},
  ch5:{intro:'分层随机抽样把“总体构成”纳入设计。先让每类群体都按设计入样，再用真实群体占比还原总体。',steps:[
    {title:'第一步：设计前检查三个条件',text:'层之间必须互不重叠，每个总体单位恰好属于一层；所有层合起来必须覆盖目标总体；层规模 Nₕ 或权重 Wₕ=Nₕ/N 需要知道或能可靠估计。每层内部再做简单随机抽样，不同层抽样相互独立。这是“分层随机抽样”，不是先把一个简单随机样本事后分组。'},
    {title:'第二步：推导总体均值估计',text:'第 h 层的总体均值是 Ȳₕ，样本均值 ȳₕ 无偏估计它。总体总和为 ΣNₕȲₕ，除以 N 得总体均值 Ȳ=Σ(Nₕ/N)Ȳₕ。把未知的 Ȳₕ 换成样本 ȳₕ，就得到 ȳₛₜ=ΣWₕȳₕ。总体总量估计则是 Ŷₛₜ=ΣNₕȳₕ。',formula:'Wₕ=Nₕ/N，ΣWₕ=1\nȳₛₜ=ΣWₕȳₕ\nŶₛₜ=ΣNₕȳₕ'},
    {title:'第三步：推导分层估计方差',text:'各层抽样独立，所以加权和的方差是每层方差乘权重平方再相加：Var(ΣWₕȳₕ)=ΣWₕ²Var(ȳₕ)。每层内部是 SRS，Var(ȳₕ)=(1−fₕ)Sₕ²/nₕ。合并即得到分层均值的方差。要特别留意权重是平方后进入方差；直接把各层 SE 按 Wₕ 相加通常不对。',formula:'Var(ȳₛₜ)=Σ Wₕ²(1−fₕ)Sₕ²/nₕ\nv(ȳₛₜ)=Σ Wₕ²(1−fₕ)sₕ²/nₕ'},
    {title:'第四步：什么时候分层能带来收益',text:'如果所有层的均值相近、层内差异小，而层间差异大，分层会削弱“这次样本碰巧多抽到哪种单位”造成的总体波动。若分层变量和目标 y 没关系，层内方差不降，收益可能不明显。分层还可以保证小但重要的群体有足够样本，即使这不是总体精度的最优配置。'},
    {title:'第五步：选择每层抽多少',text:'比例分配 nₕ=nWₕ，层内抽样比例相同，估计权重直观，适合成本和层内方差大致相同。固定总 n、成本相同且关注一个指标时，Neyman 分配 nₕ∝NₕSₕ：规模大、层内变异大的层多抽。若每层成本 cₕ 不同，理论分配为 nₕ∝NₕSₕ/√cₕ。多指标或需要每层单独报告时，通常要设置最低层样本量再折中。'}
  ],worked:{title:'城市与农村家庭平均人数',steps:['已知城市 N₁=250、农村 N₂=500，所以总体 N=750；层权重 W₁=250/750=1/3，W₂=500/750=2/3。','两层各抽 10 户；城市样本均值 ȳ₁=3.2，农村 ȳ₂=4.0。','总体平均估计 ȳₛₜ=(1/3)×3.2+(2/3)×4.0=1.0667+2.6667=3.7334 人。','如果误做简单平均 (3.2+4.0)/2=3.6，就等于假设城市和农村各占一半；但真实总体中农村户数是城市的两倍。'],result:'即使每层抽样量一样，总体估计仍由总体权重决定。样本怎么分配，与总体应该怎么加权，是两个不同问题。'},pitfalls:['把 ȳₕ 简单平均只在层规模相同等特殊情况下才对。','方差公式里用 Wₕ²；总量估计的方差则按 Nₕ² Var(ȳₕ) 加总。','Neyman 分配只在指定目标、成本及约束下最优；不能脱离条件说永远最好。']},
  ch5a:{intro:'本章是在分层抽样主公式上做压力测试：如果权重不准、样本分配偏离最优，精度会怎么变化？',steps:[
    {title:'第一步：把权重误差和抽样误差分开',text:'真实总体均值是 ΣWₕȲₕ；使用估计权重 wₕ 后，估计量变成 Σwₕȳₕ。即使 ȳₕ 平均无偏，期望也会趋近 ΣwₕȲₕ。与真值之差约为 Σ(wₕ−Wₕ)Ȳₕ。只要错误权重固定，这部分偏差不会因为每层样本量增加而消失。'},
    {title:'第二步：什么时候权重误差刚好不造成偏差',text:'若所有层均值完全相同，权重怎么分只要总和为 1，加权结果都相同；或权重误差恰好正负抵消，也可能偏差为 0。但现实中层均值通常不同，因此不能依赖这种巧合。检查权重时要核对来源、覆盖范围、统计时点和总和，层比例应归一到 1。'},
    {title:'第三步：样本增大为什么救不了偏差',text:'均方误差 MSE=方差+偏差²。随着 n 增大，层均值的抽样方差下降；如果 wₕ 不变且错误，偏差趋向固定值，MSE 最后会停在偏差²附近。于是可能出现“估计值每次都很稳定，但稳定地偏离真值”的情况。先修正权重常比盲目加样本有效。',formula:'MSE(ȳw) = Var(ȳw) + Bias(ȳw)²\nBias ≈ Σ(wₕ−Wₕ)Ȳₕ'},
    {title:'第四步：分配偏离最优时如何量化',text:'给定总 n，分层方差近似由 ΣWₕ²Sₕ²/nₕ 决定。Neyman 分配把 nₕ 放到 WₕSₕ 较大的层。若实际分配 nₕ′ 偏离最优，可把两组 nₕ 代回相同方差式，比较绝对差或相对增加比例。不能只比较“每层都分到了样本”就认为效率一样。'},
    {title:'第五步：多个指标与分层边界',text:'如果调查同时估收入、就业和教育，适合收入的 Neyman 分配不一定适合就业。实务上先定最关键指标和每层最低样本，再比较折中方案。构造层时，希望同层 y 值更集中、层与层均值差异更明显；用 x 代替 y 做分层时，x 应和目标变量高度相关。层数过多会提高维护成本并使单层样本太少。'}
  ],worked:{title:'错误权重如何留下系统偏差',steps:['真实权重：城市 1/3、农村 2/3；两层均值分别为 3.2 和 4。','真实总体均值：μ=(1/3)×3.2+(2/3)×4=3.733。','错误地各给 1/2：μ̂w=(1/2)×3.2+(1/2)×4=3.6。权重偏差贡献=3.6−3.733≈−0.133。','若每层抽 100 户，层均值可能估得更稳，但继续用 1/2、1/2，目标仍是 3.6；增加样本只降低随机波动，不改变错误的中心。'],result:'纠偏顺序：先查总体层规模与权重，再查层均值和样本分配，最后才讨论是否加样本。'},pitfalls:['“大样本一定无偏”是错的；大样本能消除某些随机误差，不能消除固定权重偏差。','权重和为 1 是加权均值的基本条件；总量估计与均值权重不要混写。','多个指标需要折中时，应明确优先级，而不是声称一个分配对全部变量最优。']},
  ch6:{intro:'比率估计的关键不是“多除一次”，而是借一个已知的辅助总量，把样本里的 y 与 x 关系带回总体。',steps:[
    {title:'第一步：画出 x 与 y 的关系',text:'每个抽样单位都同时观察目标 y 和辅助 x。比如 y 是今年利润，x 是去年利润；总体去年的总利润 X 已由完整记录知道，但今年的总利润 Y 未知。若今年和去年利润大体按比例变化，样本比率能利用这个稳定关系。'},
    {title:'第二步：从样本比率构造总体估计',text:'样本比率 r=Σy/Σx。总体的 x 总量 X 已知，就估 Y≈R·X，并用 r 代 R，得到 Ŷᴿ=Xr。若以总体均值表示，则 Ȳᴿ=X̄r。因为比率本身是随机分子除以随机分母，这个估计通常有小的偏差，不能像样本均值那样声称严格无偏。',formula:'r = ȳ/x̄ = Σyᵢ/Σxᵢ\nŶᴿ = Xr = X·(Σyᵢ/Σxᵢ)\nȲᴿ = X̄r'},
    {title:'第三步：它为什么可能更精确',text:'简单扩张估计把样本 y 均值乘 N；比率估计则先按 x 对单位规模进行校正。若 y≈R x，那么残差 eᵢ=yᵢ−R xᵢ 很小。比率估计的近似方差主要看这些残差的离散程度；y 与 x 同向且关系稳定时，残差方差可能远小于 y 本身方差。若关系弱、负相关或截距很大，残差未必小，甚至可能更差。'},
    {title:'第四步：方差近似的推理',text:'在样本量足够大时，把样本比率 r 在真比率 R 附近线性展开：r−R≈(ȳ−R x̄)/X̄。右边是残差 e=y−Rx 的样本均值除以 X̄。再套用均值的 SRS 方差式，就得到 Var(r)≈(1−f)S²ₑ/(nX̄²)。总量估计乘 X 后，方差乘 X²。',formula:'eᵢ = yᵢ − R xᵢ\nVar(r) ≈ (1−f)S²ₑ/(nX̄²)\nVar(Ŷᴿ) ≈ X² Var(r)'},
    {title:'第五步：分层里的两种比率',text:'分层样本中可以先对每层分别算 rₕ，再把各层估计总量相加；也可以先合并样本的 x、y 计算一个总体比率。各层真实比率差异很大时，单一总比率可能掩盖结构差异；每层样本都很小时，单独估各层比率又不稳定。要根据层间关系和每层样本量选择。'}
  ],worked:{title:'56 家公司的年度利润估计',steps:['总体有 N=56 家；已知去年利润总额 X=86,436（千美元）。样本抽 n=12 家，样本去年利润和 Σx=16,352，今年利润和 Σy=18,459。','样本比率 r=18,459/16,352≈1.1289，表示样本今年利润总和约为去年总和的 1.129 倍。','比率估计：Ŷᴿ=86,436×1.1289≈97,574（千美元）。','简单扩张估计：N·ȳ=56×(18,459/12)=56×1,538.25≈86,142（千美元）。','两个估计不同，因为使用了不同信息和假设。比率估计是否更精确，要看今年与去年利润关系、残差方差及近似条件；不能因为它更高就判它更好。'],result:'看到辅助变量题，先确认总体 X 是否已知、x 与 y 是否成对观测，再判断关系适不适合比率调整。'},pitfalls:['必须有总体辅助变量总量 X（或均值 X̄）；只有样本 x 不够。','比率估计是近似无偏，不等于小样本严格无偏。','比率估计点值更大或更小都不能说明更准确，精度要比较方差/标准误。']}
};
const plan = [
  ['第 1 章：建立课程地图','圈出总体、样本等关键词'],['第 1 章：闭卷回忆','用自己的例子解释抽样为何有用'],
  ['第 2 章：读懂抽样机制','整理简单随机抽样的条件'],['第 2 章：练习估计思路','重点回忆样本均值与变异'],
  ['第 3 章：比例估计','写下定性特征如何变成比例问题'],['第 3 章：比较与自测','闭卷说明比例/百分比估计的用途'],
  ['第 4 章：样本量','整理精度、风险与所需样本量'],['第 4 章：重做例题','逐步写出已知条件与判断'],
  ['第 5 章：分层设计','画出总体、层与层内样本关系'],['第 5 章：估计与权重','解释为什么要考虑各层权重'],
  ['第 5A 章：权重误差','比较真实权重与估计权重的影响'],['第 6 章：比率估计','区分目标变量和辅助变量'],
  ['综合回顾：方法选择','为不同题目写出抽样/估计选择理由'],['考前回看：错题与公式','完成清单，优先复习仍不确定的点']
];
const quiz = [
  {q:'简单随机抽样（不放回）最核心的抽取特征是什么？',options:['每个样本单位都来自同一层','从总体中随机抽取单位，抽后不放回','各单位按固定次序进入样本','只抽取总体中最典型的单位'],answer:1,why:'第 2 章从有限总体中不放回选取 n 个单位，建立简单随机抽样的基本机制。'},
  {q:'估计总体中具有某一属性的比例，最贴近哪类数据？',options:['定性属性或类别归属','每位成员的精确出生时间','仅有单位编号的数据','只有抽样顺序的数据'],answer:0,why:'第 3 章围绕 qualitative characteristics（定性特征）讨论比例和百分比。'},
  {q:'估计样本量时，材料指出应先考虑哪类问题？',options:['调查表的颜色与字体','希望达到的精度与可接受的抽样风险','只看总体名称','样本是否能整除总体'],answer:1,why:'第 4 章从希望估计得多准确、愿承担多大抽样风险等问题展开。'},
  {q:'分层随机抽样的主要结构是什么？',options:['将总体划分为互不重叠的层，并在各层分别抽样','先估计比率再随机分层','只从最大的子群抽样','将多个样本合并后才随机抽取'],answer:0,why:'第 5 章将总体划分为互不重叠且覆盖整体的子总体，再在各层独立抽样。'},
  {q:'第 5A 章讨论了哪种权重相关问题？',options:['层权重估计误差对偏差和均方误差的影响','问卷页码对样本均值的影响','总体规模单位换算','样本排序对随机性的影响'],answer:0,why:'补充材料讨论以估计的层权重替代真实层权重后，估计偏差及均方误差的变化。'},
  {q:'比率估计量的样本形式通常利用哪两类观测？',options:['目标变量 y 与辅助变量 x','两个互不相关的抽样编号','只用样本容量 n 与层数 L','总体名单与调查日期'],answer:0,why:'第 6 章对每个单位收集一对观测 (xᵢ, yᵢ)，并构造样本比率。'}
];
const storageKey='sampling-study-v1';
let state={};try{state=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{state={}}
const save=()=>localStorage.setItem(storageKey,JSON.stringify(state));
const grid=(target,items)=>{document.getElementById(target).innerHTML=items.map(x=>`<article class="lesson-card ${state[x.id]?'completed':''}" data-card="${x.id}"><div class="lesson-top"><span class="lesson-no">LESSON ${x.no}</span><span class="lesson-stage">${x.stage}</span></div><h3>${x.title}</h3><p>${x.text}</p><div class="lesson-objective">${x.objective}</div><div class="lesson-bottom"><a class="start-lesson" href="#learn/${x.id}/0">进入章节学习 <span>↗</span></a><label class="complete-toggle"><input type="checkbox" data-lesson="${x.id}" ${state[x.id]?'checked':''}> 完成</label></div><div class="card-extra"><a class="material-link" href="materials/${x.file}" target="_blank" rel="noopener">补充讲义 PDF ↗</a>${x.extra?`<br><a class="material-link" href="materials/${x.extra.file}" target="_blank" rel="noopener">${x.extra.label}（${x.extra.kind}）↗</a>`:''}</div></article>`).join('')};
grid('lessonGrid',lessons.slice(0,4));grid('lessonGridAdvanced',lessons.slice(4));
document.getElementById('lessonGrid').addEventListener('change',onLesson);document.getElementById('lessonGridAdvanced').addEventListener('change',onLesson);
function onLesson(e){if(!e.target.matches('[data-lesson]'))return;state[e.target.dataset.lesson]=e.target.checked;save();e.target.closest('.lesson-card').classList.toggle('completed',e.target.checked);updateProgress()}
const dayContainer=document.getElementById('planList');dayContainer.innerHTML=plan.map((x,i)=>`<label class="plan-day"><input type="checkbox" data-day="${i}" ${state['day'+i]?'checked':''}><span class="day-num">${String(i+1).padStart(2,'0')}</span><span class="day-content"><strong>${x[0]}</strong><small>${x[1]}</small></span><span class="day-check">✓</span></label>`).join('');
dayContainer.addEventListener('change',e=>{if(!e.target.matches('[data-day]'))return;state['day'+e.target.dataset.day]=e.target.checked;save()});
document.querySelectorAll('[data-review]').forEach(box=>{box.checked=!!state['review'+box.dataset.review];box.addEventListener('change',()=>{state['review'+box.dataset.review]=box.checked;save()})});
const note=document.getElementById('studyNote');note.value=state.note||'';note.addEventListener('input',()=>{state.note=note.value;save();document.getElementById('savedNote').textContent='已保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})});
function updateProgress(){const done=lessons.filter(x=>state[x.id]).length,pct=Math.round(done/lessons.length*100);document.getElementById('progressLabel').textContent=pct+'%';document.getElementById('progressCount').textContent=`${done} / ${lessons.length} 完成`;document.getElementById('progressBar').style.width=pct+'%';document.getElementById('progressText').textContent=done===lessons.length?'全部章节已打卡 · 回到错题与清单复习':done?`已完成 ${done} 章 · 保持这个节奏`:'刚刚起步 · 选一章开始吧'}
updateProgress();
let current=0,selected=null,checked=false;const questionEl=document.getElementById('quizQuestion'),optionsEl=document.getElementById('quizOptions'),feedback=document.getElementById('quizFeedback');
function renderQuiz(){const item=quiz[current];selected=null;checked=false;document.getElementById('quizNumber').textContent=String(current+1).padStart(2,'0');questionEl.textContent=item.q;feedback.textContent='';feedback.className='quiz-feedback';optionsEl.innerHTML=item.options.map((x,i)=>`<button class="quiz-option" data-option="${i}">${String.fromCharCode(65+i)}　${x}</button>`).join('');optionsEl.querySelectorAll('button').forEach(btn=>btn.addEventListener('click',()=>{if(checked)return;selected=Number(btn.dataset.option);optionsEl.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',Number(b.dataset.option)===selected))}))}
document.getElementById('checkAnswer').addEventListener('click',()=>{if(selected===null){feedback.textContent='先选择一个答案。';feedback.classList.add('bad');return}const item=quiz[current];checked=true;optionsEl.querySelectorAll('button').forEach(b=>{const n=Number(b.dataset.option);if(n===item.answer)b.classList.add('correct');else if(n===selected)b.classList.add('wrong')});feedback.textContent=(selected===item.answer?'回答正确。':'再想一想。')+' '+item.why;feedback.className='quiz-feedback'+(selected===item.answer?'':' bad')});
document.getElementById('nextQuestion').addEventListener('click',()=>{current=(current+1)%quiz.length;renderQuiz()});renderQuiz();


